use crate::{data::DataStore, sessions::SessionManager};
use serde_json::{json, Value};
use std::{io::{Read, Write}, net::{TcpListener, TcpStream}, sync::{Arc, Mutex, atomic::{AtomicBool, Ordering}}, thread};
use tauri::{AppHandle, Manager};

pub struct Server { stop: Arc<AtomicBool>, join: Mutex<Option<thread::JoinHandle<()>>> }
impl Server { pub fn new()->Self{Self{stop:Arc::new(AtomicBool::new(false)),join:Mutex::new(None)}} pub fn start(&self,app:AppHandle){let port=std::env::var("SHELLINK_PORT").ok().and_then(|v|v.parse().ok()).unwrap_or(7070);let Ok(listener)=TcpListener::bind(("127.0.0.1",port))else{return};let _=listener.set_nonblocking(true);let stop=self.stop.clone();*self.join.lock().unwrap()=Some(thread::spawn(move||{while !stop.load(Ordering::Relaxed){match listener.accept(){Ok((stream,_))=>{let app=app.clone();thread::spawn(move||handle(stream,app));},Err(e) if e.kind()==std::io::ErrorKind::WouldBlock=>thread::sleep(std::time::Duration::from_millis(30)),Err(_)=>break}}}));} pub fn stop(&self){self.stop.store(true,Ordering::Relaxed);if let Some(join)=self.join.lock().unwrap().take(){let _=join.join();}} }
fn handle(mut stream:TcpStream,app:AppHandle){let mut buf=vec![0u8;4<<20];let Ok(n)=stream.read(&mut buf)else{return};let raw=String::from_utf8_lossy(&buf[..n]);let Some((head,body))=raw.split_once("\r\n\r\n")else{return};if !head.starts_with("POST /shellink/mcp "){respond(&mut stream,404,json!({"error":"not found"}));return}let auth=head.lines().find(|l|l.to_ascii_lowercase().starts_with("authorization:")).and_then(|l|l.split_once(':')).map(|(_,v)|v.trim()).unwrap_or("");let expected=app.try_state::<Option<DataStore>>().and_then(|s|s.inner().as_ref().and_then(|db|db.mcp_info().ok())).and_then(|v|v.get("token").and_then(Value::as_str).map(str::to_owned));if expected.as_deref().is_some_and(|t|auth!=format!("Bearer {}",t)){respond(&mut stream,401,json!({"error":"unauthorized"}));return}let Ok(request)=serde_json::from_str::<Value>(body.trim())else{respond(&mut stream,400,json!({"error":"invalid json"}));return};let id=request.get("id").cloned().unwrap_or(Value::Null);let result=dispatch(&app,request.get("method").and_then(Value::as_str).unwrap_or(""),request.get("params").unwrap_or(&Value::Null));respond(&mut stream,200,json!({"jsonrpc":"2.0","id":id,"result":result}));}
fn dispatch(app:&AppHandle,method:&str,params:&Value)->Value{match method{"initialize"=>json!({"protocolVersion":"2024-11-05","serverInfo":{"name":"shellink","version":"0.2.4"},"capabilities":{"tools":{}}}),"notifications/initialized"=>json!({}),"tools/list"=>json!({"tools":tools()}),"tools/call"=>call_tool(app,params),_=>json!({})}}
fn tools()->Vec<Value>{["shellink_list_profiles","shellink_create_profile","shellink_list_sessions","shellink_create_session","shellink_session_state","shellink_read_output","shellink_send_input","shellink_close_session"].into_iter().map(|name|json!({"name":name,"description":"Shellink terminal operation","inputSchema":{"type":"object"}})).collect()}
fn call_tool(app:&AppHandle,p:&Value)->Value {
    let name=p.get("name").and_then(Value::as_str).unwrap_or(""); let a=p.get("arguments").unwrap_or(&Value::Null);
    let Some(db)=app.try_state::<Option<DataStore>>().and_then(|s|s.inner().as_ref().map(|x|x as &DataStore)) else { return json!({"isError":true,"content":[{"type":"text","text":"Rust data store unavailable"}]}); };
    let result: Result<Value,String> = match name {
        "shellink_list_profiles"=>db.profiles(None), "shellink_create_profile"=>db.profile_create(a), "shellink_list_sessions"=>db.sessions(),
        "shellink_create_session"=>app.try_state::<Arc<SessionManager>>().ok_or_else(||"session manager unavailable".to_string()).and_then(|m|m.create(app,db,a.get("profileId").and_then(Value::as_str).ok_or_else(||"profileId is required".to_string())?,"","mcp","AUTO",0,0)),
        "shellink_session_state"=>db.session_state(a.get("id").and_then(Value::as_str).unwrap_or("")),
        "shellink_read_output"=>db.history_chunks(a.get("id").and_then(Value::as_str).unwrap_or(""),0,a.get("limit").and_then(Value::as_i64).unwrap_or(200)),
        "shellink_send_input"=>app.try_state::<Arc<SessionManager>>().ok_or_else(||"session manager unavailable".to_string()).and_then(|m|m.input(db,a.get("id").and_then(Value::as_str).ok_or_else(||"id is required".to_string())?,a.get("text").and_then(Value::as_str).ok_or_else(||"text is required".to_string())?,false)),
        "shellink_close_session"=>app.try_state::<Arc<SessionManager>>().ok_or_else(||"session manager unavailable".to_string()).and_then(|m|m.close(db,a.get("id").and_then(Value::as_str).ok_or_else(||"id is required".to_string())?)), _=>Err("unknown tool".into())
    };
    match result { Ok(v)=>json!({"content":[{"type":"text","text":v.to_string()}]}), Err(e)=>json!({"isError":true,"content":[{"type":"text","text":e}]}) }
}
fn respond(stream:&mut TcpStream,status:u16,value:Value){let body=value.to_string();let _=write!(stream,"HTTP/1.1 {} OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",status,body.len(),body);}
